int main(int argc,char**argv){int fps=argc>2?atoi(argv[2]):30;bool consumer=argc>3;CHECK(CoInitializeEx(nullptr,COINIT_MULTITHREADED));auto dll=LoadLibraryW(L"BandHeartBeatDirectShow-test.dll");if(!dll)return 2;auto get=reinterpret_cast<HRESULT(WINAPI*)(REFCLSID,REFIID,void**)>(GetProcAddress(dll,"DllGetClassObject"));const CLSID id={0x5b4131af,0x3298,0x47aa,{0x9c,0x12,0x33,0x40,0x7a,0x81,0x91,0x4b}};ComPtr<IClassFactory>factory;CHECK(get(id,IID_PPV_ARGS(&factory)));ComPtr<IBaseFilter>source;CHECK(factory->CreateInstance(nullptr,IID_PPV_ARGS(&source)));ComPtr<IGraphBuilder>graph;CHECK(CoCreateInstance(CLSID_FilterGraph,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&graph)));ComPtr<IBaseFilter>renderer;CaptureConsumer*observer=nullptr;if(consumer){observer=new CaptureConsumer();observer->pin->expectedInterval=10000000/fps;observer->pin->failCommit=argc>4;renderer.Attach(observer);}else{CHECK(CoCreateInstance(CLSID_NullRenderer,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&renderer)));}CHECK(graph->AddFilter(source.Get(),L"BandHeartBeat isolated"));CHECK(graph->AddFilter(renderer.Get(),L"Quartz NullRenderer"));ComPtr<IPin>output,input;CHECK(source->FindPin(L"Output",&output));ComPtr<IEnumPins>pins;CHECK(renderer->EnumPins(&pins));CHECK(pins->Next(1,&input,nullptr));ComPtr<IAMStreamConfig>config;CHECK(output.As(&config));int count=0,bytes=0;CHECK(config->GetNumberOfCapabilities(&count,&bytes));std::vector<BYTE>caps(bytes);AM_MEDIA_TYPE*selected=nullptr;CHECK(config->GetStreamCaps(argc>1?1:0,&selected,caps.data()));reinterpret_cast<VIDEOINFOHEADER*>(selected->pbFormat)->AvgTimePerFrame=10000000/fps;CHECK(config->SetFormat(selected));CoTaskMemFree(selected->pbFormat);CoTaskMemFree(selected);CHECK(graph->ConnectDirect(output.Get(),input.Get(),nullptr));AM_MEDIA_TYPE negotiated{};CHECK(output->ConnectionMediaType(&negotiated));if(reinterpret_cast<VIDEOINFOHEADER*>(negotiated.pbFormat)->AvgTimePerFrame!=10000000/fps||negotiated.subtype!=(argc>1?MEDIASUBTYPE_RGB24:MEDIASUBTYPE_RGB32))return 8;CoTaskMemFree(negotiated.pbFormat);config.Reset();ComPtr<IAMDroppedFrames>stats;CHECK(output.As(&stats));ComPtr<IMediaControl>control;CHECK(graph.As(&control));CHECK(control->Pause());if(argc>4){auto begun=GetTickCount64();auto hr=source->Run(0);FILTER_STATE failed_state;source->GetState(0,&failed_state);if(hr!=E_OUTOFMEMORY||failed_state!=State_Stopped||observer->pin->count||GetTickCount64()-begun>1000)return 11;std::cout<<"PASS allocatorCommit E_OUTOFMEMORY propagated; stopped/no samples/bounded\n";control->Stop();graph->Disconnect(output.Get());graph->Disconnect(input.Get());return 0;}CHECK(control->Run());Sleep(1200);long n=0;CHECK(stats->GetNumNotDropped(&n));CHECK(control->Stop());if(n<fps||n>fps*2){std::cerr<<"unexpected deliveries "<<n<<"\n";return 3;}std::cout<<"PASS real Quartz FilterGraph -> "<<(consumer?"capture consumer IMediaSample2":"NullRenderer")<<" accepted "<<n<<" samples in1200ms requested="<<fps<<"fps consumer="<<consumer<<"\n";CHECK(control->Run());Sleep(300);CHECK(control->Stop());long again;CHECK(stats->GetNumNotDropped(&again));if(again<=n)return 4;if(observer&&(!observer->pin->valid||observer->pin->count<static_cast<unsigned>(fps))){std::cerr<<"capture sample property failure\n";return 9;}CHECK(graph->Disconnect(output.Get()));CHECK(graph->Disconnect(input.Get()));CHECK(graph->RemoveFilter(renderer.Get()));CHECK(graph->RemoveFilter(source.Get()));stats.Reset();control.Reset();input.Reset();output.Reset();pins.Reset();renderer.Reset();graph.Reset();source.Reset();factory.Reset();auto unload=reinterpret_cast<HRESULT(WINAPI*)()>(GetProcAddress(dll,"DllCanUnloadNow"));CHECK(unload());FreeLibrary(dll);CoUninitialize();std::cout<<"PASS graph stop/restart/disconnect/unload; no registry/physical camera\n";}

